'use strict';
const C=ShelfCore,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='shelf.library.v1',PREF='shelf.preferences.v1';
const COLORS={'Design':'#b7a77c','AI & tools':'#89a789','Creative':'#af9cb8','Marketing':'#b89983','Food & coffee':'#b0a181','Fitness':'#89a9a0','Life':'#b9a0a3','Film & culture':'#b39696','Finance':'#87a7ad','Parenting':'#b8a8bd','Work & learning':'#9ca7b7','Style':'#baac95','Unsorted':'#b1b9ab'};
const ICONS={start:'↗',tasks:'↗',all:'▦',unread:'◷',favorite:'☆',archived:'▤',trash:'⌫'};
let data={version:1,items:[],annotations:{},collections:[],guides:[]},server=false,connection=false,revision=0,view='start',goalText='',goalChoice='',guideCategory='All',filter='all',query='',layout='grid',sort='position',selected=new Set(),selecting=false,limit=60,detailId=null,detailTab='overview',saveTimer,toastTimer,renderTimer,serverSaving=false,pendingSave=false,undoAction=null,lastFocus=null;
let ready;
let aiEnabled=false,aiBusy=false,aiResult=null,aiQuery='',aiScores=[],aiStatus='AI is off. Basic matching is available.';
let dbPromise;
function browserDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('shelf-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('library');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return dbPromise;}
async function browserRead(){try{const db=await browserDB();return await new Promise((resolve,reject)=>{const t=db.transaction('library');const r=t.objectStore('library').get('current');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}catch{return null;}}
async function browserWrite(value){try{const db=await browserDB();await new Promise((resolve,reject)=>{const t=db.transaction('library','readwrite');t.objectStore('library').put(value,'current');t.oncomplete=resolve;t.onerror=()=>reject(t.error);});}catch{try{localStorage.setItem(KEY,JSON.stringify(value));}catch{toast('Device storage is full. Export a backup to keep your latest changes.');}}}
function annotation(id){return data.annotations[id]||{};}
function category(x){return annotation(x.id).category||x.category;}
function itemById(id){return data.items.find(x=>x.id===id);}
function patch(id,change){data.annotations[id]={...annotation(id),...change};persist();render();}
function toast(text,undo){clearTimeout(toastTimer);undoAction=undo||null;$('#toast').innerHTML=`<span>${esc(text)}</span>${undo?'<button id="undo">Undo</button>':''}`;$('#toast').hidden=false;if(undo)$('#undo').onclick=()=>{undoAction();$('#toast').hidden=true;};toastTimer=setTimeout(()=>$('#toast').hidden=true,6500);}
function persist(){browserWrite(JSON.parse(JSON.stringify(data)));if(server){pendingSave=true;clearTimeout(saveTimer);saveTimer=setTimeout(saveServer,400);}}

async function saveServer(){if(serverSaving)return;serverSaving=true;while(pendingSave){pendingSave=false;try{const res=await fetch('/api/library',{method:'POST',headers:{'Content-Type':'application/json','If-Match':String(revision)},body:JSON.stringify(data)});if(res.status===409){toast('Another window changed this library. Export your changes, then reload to merge them.');server=false;$('#storage-label').textContent='Changes saved in this browser';break;}if(!res.ok)throw Error();revision=(await res.json()).revision;$('#storage-label').textContent='Saved on your Mac';}catch{toast('Local library is offline. Changes are kept in this browser; reopen the local app to reconnect.');server=false;$('#storage-label').textContent='Saved in this browser';break;}}serverSaving=false;}
function prefs(){try{localStorage.setItem(PREF,JSON.stringify({layout,sort}));}catch{}}
function navItem(key,label,count,icon){return `<button class="navitem ${view===key?'active':''}" data-view="${esc(key)}"><span class="nav-icon">${icon}</span><span>${esc(label)}</span><span class="count">${count||''}</span></button>`;}
function renderNav(){const live=data.items.filter(x=>!annotation(x.id).trashed&&!annotation(x.id).archived);$('#navigation').innerHTML=[navItem('start','For now',null,ICONS.start),...(data.guides?.length?[navItem('tasks','Saved methods',data.guides.length,ICONS.tasks)]:[]),navItem('all','All saves',live.length,ICONS.all),navItem('unread','To revisit',live.filter(x=>!annotation(x.id).read).length,ICONS.unread),navItem('favorite','Favorites',live.filter(x=>annotation(x.id).favorite).length,ICONS.favorite),navItem('archived','Archive',data.items.filter(x=>annotation(x.id).archived&&!annotation(x.id).trashed).length,ICONS.archived)].join('');$('#topics').innerHTML=C.TOPICS.filter(t=>live.some(x=>category(x)===t)).map(t=>`<button data-view="topic:${esc(t)}" class="navitem ${view==='topic:'+t?'active':''}"><span class="topic-dot" style="--topic:${COLORS[t]}"></span><span>${esc(t)}</span><span class="count">${live.filter(x=>category(x)===t).length}</span></button>`).join('');$('#collections').innerHTML=data.collections.length?data.collections.map(c=>navItem('collection:'+c.id,c.name,live.filter(x=>(annotation(x.id).collections||[]).includes(c.id)).length,'▱')).join(''):'<p class="collection-empty">A place for your next project.<br><button class="text-btn" id="first-collection">+ Create a collection</button></p>';$('#first-collection')?.addEventListener('click',newCollection);}
function render(){document.body.classList.toggle('has-saves',!!data.items.length);document.body.classList.toggle('home-view',view==='start');document.querySelectorAll('.primary-tabs button').forEach(b=>b.classList.toggle('active',b.id===(view==='start'?'tab-start':'tab-library')));renderNav();renderTasks();renderStart();const labels={start:[data.items.length?'What would you like to do?':'Saved for later. Useful right now.',data.items.length?'Find one useful place to start, in the things you saved.':'Find the good thing you saved. Then put it to use.'],tasks:['Use my saves','Start with what you want to do. Find a method, then take the next step.'],all:['All saves','Everything you wanted to come back to.'],unread:['To revisit','A little space for what you haven’t explored yet.'],favorite:['Favorites','The ones you want to keep close.'],archived:['Archive','Finished for now. Still here when you need them.'],trash:['Trash','Removed from your library. Restore them anytime.']};let name=labels[view]||[view.startsWith('topic:')?view.slice(6):data.collections.find(c=>c.id===view.slice(11))?.name||'Collection','A smaller shelf. A clearer view.'];$('#page-title').innerHTML=esc(name[0])+(view==='start'?'':'<span class="serif-dot">.</span>');$('#page-subtitle').textContent=name[1];const visible=C.filterItems(data.items,data,view,filter,query,sort);$('#result-count').textContent=`${visible.length} ${visible.length===1?'save':'saves'}${query?' matching “'+query+'”':''}`;$('#cards').hidden=['start','tasks'].includes(view);$('#save-toolbar').hidden=['start','tasks'].includes(view)||!data.items.length;$('.result-row').hidden=['start','tasks'].includes(view)||!data.items.length;$('#sync').hidden=!connection;$('#cards').className=(layout==='list'?'list-view':'')+(selecting?' selecting':'');$('#cards').innerHTML=visible.slice(0,limit).map(card).join('');$('#load-more').hidden=['start','tasks'].includes(view)||visible.length<=limit;$('#empty').hidden=['start','tasks'].includes(view)||visible.length>0||!data.items.length;$('#empty-title').textContent=query?'No matching saves.':view==='favorite'?'Keep your best finds close.':view==='trash'?'Your trash is empty.':'A little room to begin.';$('#empty-copy').textContent=query?'Try a title, creator, topic, or a word from your reading notes.':view==='favorite'?'Tap the star on any save to find it here.':'Add a link or import your existing saves. You can organize them as you go.';$('#empty-action').textContent=data.items.length?'Show all saves':'Add your first save';$('#import-banner').hidden=data.items.length>0||['start','tasks'].includes(view);$('#bulk').hidden=!selecting;$('#selected-count').textContent=selected.size+' selected';$('#select-mode').textContent=selecting?'Selecting…':'Select';$('#clear-filters').hidden=!query&&filter==='all';$('#grid-view').classList.toggle('active',layout==='grid');$('#list-view').classList.toggle('active',layout==='list');document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));$('#sort').value=sort;if(data.scan){const d=new Date(data.scan.at);$('#footer-status').textContent=`${data.items.length} saves · Last collection scan ${isNaN(d)?'saved earlier':d.toLocaleDateString('en',{month:'short',day:'numeric'})}${data.scan.complete?'':' · Partial scan'}`;}else $('#footer-status').textContent=(data.items.length&&data.items.every(x=>x.id.startsWith('example-'))?'Example notes · Stored on this device':'Stored on this device');}
function card(x){const a=annotation(x.id),cat=category(x),cover=server&&!x.image?.startsWith('data:')?'/media/'+encodeURIComponent(x.id)+'.jpg':C.imageURL(x.image),has=Boolean(cover);return `<article class="card ${selected.has(x.id)?'selected':''}" data-id="${esc(x.id)}"><label class="card-select"><input type="checkbox" aria-label="Select ${esc(x.title)}" data-select="${esc(x.id)}" ${selected.has(x.id)?'checked':''}></label><button class="cover-button" data-open="${esc(x.id)}" aria-label="Open ${esc(x.title)}"><div class="cover ${has?'':'no-image'}" data-topic="${esc(cat)}">${has?`<img loading="lazy" src="${esc(cover)}" alt="" referrerpolicy="no-referrer">`:''}<span class="type-badge">${x.type==='video'?'▷':'▧'} ${x.type==='video'?'Video':x.type==='note'?'Post':'Link'}${x.duration?' · '+Math.floor(x.duration/60)+':'+String(Math.round(x.duration%60)).padStart(2,'0'):''}</span></div></button><button class="card-fav ${a.favorite?'on':''}" data-favorite="${esc(x.id)}" aria-label="${a.favorite?'Unfavorite':'Favorite'} ${esc(x.title)}">${a.favorite?'★':'☆'}</button><div class="card-body"><div class="card-category">${esc(cat)}</div><button class="title-btn" data-open="${esc(x.id)}"><h2>${esc(x.title)}</h2></button><p class="card-summary">${esc(a.note||x.summary||x.description||'Saved for later. Open the original when you’re ready.')}</p><div class="card-bottom"><span class="read-dot ${a.read?'read':''}" title="${a.read?'Read':'Not read yet'}"></span><span class="card-author">${esc(x.author||new URL(x.url||'https://example.com').hostname)}</span>${x.hasContent?'<span class="notes-badge">Saved text</span>':''}<button class="icon-btn" data-open="${esc(x.id)}" aria-label="View details">↗</button></div></div></article>`;}
function handleBrokenImages(){document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.closest('.cover')){e.target.parentElement.classList.add('no-image');e.target.remove();}},true);}
function closeDetail(){if(!detailId)return;$('#detail').hidden=true;$('#detail-backdrop').hidden=true;document.body.style.overflow='';detailId=null;render();if(lastFocus?.isConnected)lastFocus.focus();}
function openDetail(id,tab='overview'){const x=itemById(id);if(!x)return;if(!detailId)lastFocus=document.activeElement;detailId=id;detailTab=tab;const a=annotation(id),cover=server&&!x.image?.startsWith('data:')?'/media/'+encodeURIComponent(id)+'.jpg':C.imageURL(x.image);$('#detail').innerHTML=`<div class="detail-top"><button class="icon-btn" id="close-detail" aria-label="Close details">×</button><small>YOUR SAVE</small><span class="spacer"></span><button id="detail-favorite" class="icon-btn" aria-label="${a.favorite?'Remove favorite':'Favorite this save'}">${a.favorite?'★':'☆'}</button><button id="detail-open" class="btn primary">Open original ↗</button></div><div class="detail-content"><div class="cover detail-hero ${cover?'':'no-image'}" data-topic="${esc(category(x))}">${cover?`<img src="${esc(cover)}" alt="" referrerpolicy="no-referrer">`:''}</div><div class="detail-category">${esc(category(x))} <span> / ${x.type==='video'?'VIDEO':'SAVED LINK'}</span></div><h2>${esc(x.title)}</h2><div class="detail-meta"><span>${esc(x.author||'Saved link')}</span><span>•</span><span>${x.description||x.transcript?'Saved source text':x.research?'Saved research · full post not loaded':'Title & cover only'}</span></div><div class="details-controls"><button id="detail-read" class="btn">${a.read?'✓ Read':'○ Mark as read'}</button><button id="detail-archive" class="btn">${a.archived?'↩ Unarchive':'▤ Archive'}</button></div><div class="detail-tabs">${['overview','source','notes'].map(t=>`<button data-tab="${t}" class="${tab===t?'active':''}">${{overview:'Overview',source:'Source',notes:'My notes'}[t]}</button>`).join('')}</div><div id="detail-pane">${detailPane(x,a,tab)}</div><div class="detail-bottom"><button id="detail-trash" class="text-btn ${a.trashed?'':'danger'}">${a.trashed?'↩ Restore save':'Move to trash'}</button><small class="muted">${server?'Saved on your Mac':'Saved in this browser'}</small></div></div>`;$('#detail').hidden=false;$('#detail-backdrop').hidden=false;document.body.style.overflow='hidden';$('#close-detail').onclick=closeDetail;$('#detail-open').onclick=()=>openOriginal(x);$('#detail-favorite').onclick=()=>{patch(id,{favorite:!a.favorite});openDetail(id,detailTab);};$('#detail-read').onclick=()=>{patch(id,{read:!a.read});openDetail(id,detailTab);};$('#detail-archive').onclick=()=>{patch(id,{archived:!a.archived});openDetail(id,detailTab);};$('#detail-trash').onclick=()=>{const old=!!a.trashed;patch(id,{trashed:!old});closeDetail();toast(old?'Save restored.':'Moved to trash.',()=>patch(id,{trashed:old}));};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openDetail(id,b.dataset.tab));$('#note-text')?.addEventListener('input',e=>{data.annotations[id]={...annotation(id),note:e.target.value};persist();});$('#detail-category')?.addEventListener('change',e=>{patch(id,{category:e.target.value});openDetail(id,detailTab);});document.querySelectorAll('[data-collection-check]').forEach(c=>c.onchange=()=>{let list=new Set(annotation(id).collections||[]);c.checked?list.add(c.dataset.collectionCheck):list.delete(c.dataset.collectionCheck);patch(id,{collections:[...list]});});$('#load-content')?.addEventListener('click',()=>loadContent(x));if(!lastFocus||tab==='overview')$('#close-detail').focus();}
function detailPane(x,a,tab){const canLoad=server&&/^[a-f0-9]{24}$/.test(x.id);if(tab==='notes')return `<section class="detail-section"><h3>A note to your future self</h3><textarea id="note-text" class="note-area" placeholder="Why did you save this? What will you use it for?" aria-label="Personal note">${esc(a.note||'')}</textarea><p class="muted">Changes save automatically.</p></section>`;if(tab==='source')return `${x.videoURL?`<video class="source-video" controls preload="none" src="${esc(C.safeURL(x.videoURL))}"></video>`:''}<section class="detail-section"><h3>Original post text</h3><div class="source-text">${esc(x.description||'The full post has not been imported yet.')}</div>${canLoad&&!x.description?'<button id="load-content" class="btn" style="margin-top:15px">Load full post</button>':''}</section>${x.transcript?`<section class="detail-section"><h3>Saved transcript</h3><div class="source-text">${esc(x.transcript)}</div></section>`:''}<p class="restore-note">${esc(x.coverage||'Metadata and source content are kept separately. Open the original for its latest version.')}</p>`;
return `${x.research?`<section class="detail-section"><h3>What you can use</h3><p>${esc(x.research.decision)}</p><ul class="anchor-list">${x.research.points.map(p=>'<li><strong>'+esc(p[0])+'</strong><br>'+esc(p[1])+'</li>').join('')}</ul><p class="restore-note">${esc(x.research.limits)}</p></section>`:''}${x.summary?`<section class="detail-section"><h3>Reading notes</h3><p>${esc(x.summary)}</p></section>`:x.description?`<section class="detail-section"><h3>Post preview</h3><p>${esc(x.description.slice(0,500))}${x.description.length>500?'…':''}</p><p class="muted">Read the saved text in Source.</p></section>`:`<section class="detail-section"><h3>The original post</h3><p>The full post has not been loaded here. Open the original to read it${canLoad?', or load its text here':''}.</p>${canLoad?'<button id="load-content" class="btn" style="margin-top:15px">Load full post</button>':''}</section>`}${x.readingNotes?`<section class="detail-section"><h3>From your earlier research</h3><p>${esc(x.readingNotes)}</p></section>`:''}${x.anchors?.length?`<section class="detail-section"><h3>Where to look</h3><ul class="anchor-list">${x.anchors.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul></section>`:''}${x.limits?`<section class="detail-section"><h3>Context & limitations</h3><p>${esc(x.limits)}</p></section>`:''}${x.resources?.length?`<section class="detail-section"><h3>Related sources</h3><div class="resources">${x.resources.map(u=>`<a href="${esc(C.safeURL(u))}" target="_blank" rel="noopener noreferrer">${esc(u)} ↗</a>`).join('')}</div></section>`:''}<section class="detail-section"><h3>Keep it organized</h3><label for="detail-category">Topic <span class="muted">· suggestions are editable</span></label><select id="detail-category">${C.TOPICS.map(t=>`<option ${category(x)===t?'selected':''}>${esc(t)}</option>`).join('')}</select><label>Collections</label>${data.collections.length?data.collections.map(c=>`<label class="checkbox-label"><input type="checkbox" data-collection-check="${esc(c.id)}" ${(a.collections||[]).includes(c.id)?'checked':''}>${esc(c.name)}</label>`).join(''):'<p class="muted">Create a collection in the sidebar to group saves for a project.</p>'}${x.tags?.length?'<div style="margin-top:13px">'+x.tags.map(t=>'<span class="tag">'+esc(t)+'</span>').join('')+'</div>':''}</section>`;}
function openOriginal(x){const url=server&&/^[a-f0-9]{24}$/.test(x.id)?'/api/open?id='+encodeURIComponent(x.id):C.safeURL(x.url);if(url)window.open(url,'_blank','noopener,noreferrer');else toast('This save does not have a source link.');}
function modal(html){lastFocus=document.activeElement;$('#modal-body').innerHTML='<button class="icon-btn modal-close" id="close-modal" aria-label="Close dialog">×</button>'+html;$('#close-modal').onclick=()=>$('#modal').close();$('#modal').showModal();}
function newCollection(){modal('<h2>A shelf for something.</h2><p>Group saves around a project, a question, or an idea.</p><form id="collection-form"><label class="form-label" for="collection-name">Collection name</label><input class="form-input" id="collection-name" maxlength="60" placeholder="e.g. Next app, Home ideas…" required><div class="modal-actions"><button class="btn primary">Create collection</button></div></form>');$('#collection-name').focus();$('#collection-form').onsubmit=e=>{e.preventDefault();const name=$('#collection-name').value.trim();if(!name)return;if(data.collections.some(c=>c.name.toLowerCase()===name.toLowerCase()))return toast('That collection already exists.');const c={id:'c-'+crypto.randomUUID(),name};data.collections.push(c);persist();navigate('collection:'+c.id);$('#modal').close();toast('Collection created.');};}
function navigate(v){closeNavigation();view=v;limit=60;selected.clear();selecting=false;render();document.body.classList.remove('nav-open');window.scrollTo({top:0,behavior:'instant'});}
function showAdd(){modal(`<h2>Save it for when you need it.</h2><p>Copy a link or tap Share → Copy link in your app. Paste it below — extra words are fine.</p><p class="muted">No Xiaohongshu login is needed. A link saves the reference; paste a passage or add a note to make its content searchable. This beta does not automatically read private posts or watch videos.</p><form id="add-form"><label class="form-label" for="save-url">Link or share text</label><textarea class="form-input" id="save-url" rows="3" required placeholder="Paste here…"></textarea><p class="muted">You can paste several links at once.</p><label class="form-label" for="save-title">A name you will remember (optional)</label><input class="form-input" id="save-title" maxlength="300" placeholder="e.g. The coffee recipe I want to try"><details><summary>Add what this save says (recommended)</summary><textarea id="save-note" class="form-input" rows="3" placeholder="Why you saved this…" aria-label="Personal note"></textarea></details><div id="add-error" class="modal-error" role="alert"></div><div class="modal-actions"><button type="button" id="add-import" class="text-btn">Import a file instead</button><button class="btn primary">Save to library</button></div></form>`);$('#save-url').focus();$('#add-import').onclick=()=>{$('#modal').close();$('#import-file').click();};$('#add-form').onsubmit=e=>{e.preventDefault();const rows=C.sharedLinks($('#save-url').value);if(!rows.length)return $('#add-error').textContent='No link found. Copy a link starting with https:// and paste it here.';const title=$('#save-title').value.trim(),note=$('#save-note').value.trim();if(rows.length===1&&title)rows[0].title=title;const before=JSON.parse(JSON.stringify(data));for(const x of rows){const existing=data.items.find(v=>v.url===x.url);if(existing&&x.title===new URL(x.url).hostname)x.title=existing.title;x.position=-Date.now();if(note){const id=existing?.id||x.id;data.annotations[id]={...annotation(id),note};}}const result=C.mergeItems(data.items,rows);data.items=result.items;persist();query='';$('#search').value='';filter='all';sort='recent';navigate('all');$('#modal').close();toast(result.added?`${result.added} ${result.added===1?'save is':'saves are'} ready. Open a card to read or add a note.`:'Already saved. Your existing notes are kept.',()=>{data=before;persist();render();});};}
function showSettings(){modal(`<h2>Your library.</h2><p>${data.items.length} saves, ${data.collections.length} collections. ${server?'Your Mac keeps the library and cover cache.':'This browser keeps your saves. Export a backup before changing devices or clearing browser data.'}</p><div class="settings-option"><div>Export backup<small>All saves, collections and personal notes · JSON</small></div><button id="export" class="btn">Export</button></div><div class="settings-option"><div>Import saves<small>RedBot or legacy Shelf JSON, Xiaohongshu JSON, bookmark HTML or CSV</small></div><button id="import" class="btn">Import</button></div><div class="settings-option"><div>Trash<small>Removing a save here never changes Xiaohongshu.</small></div><button id="trash-view" class="btn">Open trash</button></div>${view.startsWith('collection:')?'<div class="settings-option"><div>Current collection<small>Rename or remove it. Saves are kept.</small></div><button id="rename-collection" class="btn">Manage</button></div>':''}<div class="settings-option"><div>Storage<small>${server?'Local files + browser recovery copy':'Browser storage · no cloud upload'}</small></div><span class="tag">Private</span></div>${server?'<div class="settings-option"><div>Quit local app<small>Stops the local connection. Your library is kept.</small></div><button id="quit-local" class="btn">Quit</button></div>':''}<p style="margin-top:15px">Topics are suggested from titles. Reading notes come from previously saved research; they are not a claim that every post has been fully reviewed.</p>`);$('#export').onclick=exportBackup;$('#import').onclick=()=>{$('#modal').close();$('#import-file').click();};$('#trash-view').onclick=()=>{$('#modal').close();navigate('trash');};$('#rename-collection')?.addEventListener('click',manageCollection);$('#quit-local')?.addEventListener('click',async()=>{await saveServer();try{const res=await fetch('/api/quit',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!res.ok)throw Error();server=false;$('#modal').close();$('#storage-label').textContent='Local app stopped';toast('Local app stopped. Reopen RedBot.app to reconnect.');}catch{toast('Could not stop the local app. Please try again.');}});}
function manageCollection(){const id=view.slice(11),c=data.collections.find(c=>c.id===id);if(!c)return;modal(`<h2>Edit collection.</h2><form id="edit-collection"><input class="form-input" id="rename-name" value="${esc(c.name)}" required maxlength="60"><div class="modal-actions"><button type="button" class="text-btn danger" id="remove-collection">Remove collection</button><button class="btn primary">Save name</button></div></form><p class="restore-note">Removing the collection keeps every save in your library.</p>`);$('#edit-collection').onsubmit=e=>{e.preventDefault();const name=$('#rename-name').value.trim();if(!name)return;c.name=name;persist();render();$('#modal').close();};$('#remove-collection').onclick=()=>{const snapshot=JSON.parse(JSON.stringify({collections:data.collections,annotations:data.annotations}));data.collections=data.collections.filter(x=>x.id!==id);for(const a of Object.values(data.annotations))a.collections=(a.collections||[]).filter(x=>x!==id);persist();navigate('all');$('#modal').close();toast('Collection removed. Saves kept.',()=>{data.collections=snapshot.collections;data.annotations=snapshot.annotations;persist();render();});};}
async function exportBackup(){let out=JSON.parse(JSON.stringify(data));if(server){toast('Preparing your backup…');try{const res=await fetch('/api/export');if(res.ok)out={...await res.json(),annotations:data.annotations,collections:data.collections};}catch{}}const blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='RedBot-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup downloaded. Keep it somewhere safe.');}
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++;}else quote=!quote;}else if(!quote&&(c===','||c==='\n')){row.push(cell);cell='';if(c==='\n'){rows.push(row);row=[];}}else if(c!=='\r')cell+=c;}if(cell||row.length){row.push(cell);rows.push(row);}const heads=rows.shift().map(x=>x.trim().toLowerCase());return rows.filter(r=>r.some(Boolean)).map(r=>Object.fromEntries(heads.map((k,i)=>[k,r[i]||''])));}
async function importFile(file){if(!file)return;try{if(file.size>45*1024*1024)throw Error('This file is too large. Please import a backup smaller than 45 MB.');const text=await file.text();let obj;if(/\.html?$/i.test(file.name)){const doc=new DOMParser().parseFromString(text,'text/html');obj=[...doc.querySelectorAll('a[href]')].map(a=>({url:a.getAttribute('href'),title:a.textContent}));}else if(/\.csv$/i.test(file.name))obj=parseCSV(text);else obj=JSON.parse(text);const rows=C.extract(obj);if(rows.length>20000)throw Error('Please import fewer than 20,000 saves at a time.');const before=JSON.parse(JSON.stringify(data));const result=C.mergeItems(data.items,rows);data.items=result.items;if(obj.version===1){if(obj.goalState&&!data.goalState?.plan)data.goalState=C.normalizeGoalState(obj.goalState);if(Array.isArray(obj.guides)){const guides=new Map((data.guides||[]).map(g=>[g.id,g]));obj.guides.map(C.normalizeGuide).filter(Boolean).forEach(g=>guides.set(g.id,g));data.guides=[...guides.values()];}if(Array.isArray(obj.collections))for(const c of obj.collections){if(c&&typeof c.id==='string'&&typeof c.name==='string'&&!data.collections.some(x=>x.id===c.id))data.collections.push({id:c.id,name:c.name.slice(0,60)});}if(obj.annotations&&typeof obj.annotations==='object')for(const x of data.items){let a=obj.annotations[x.id];if(a&&typeof a==='object'){const clean={read:!!a.read,favorite:!!a.favorite,archived:!!a.archived,trashed:!!a.trashed,note:C.clean(a.note),category:C.TOPICS.includes(a.category)?a.category:undefined,collections:(Array.isArray(a.collections)?a.collections:[]).filter(t=>typeof t==='string')};data.annotations[x.id]={...clean,...annotation(x.id),note:annotation(x.id).note||clean.note};}}}persist();navigate('all');toast(`${result.added} new saves imported. ${rows.length-result.added} existing saves merged.`,()=>{data=before;persist();render();});}catch(e){toast('Import failed: '+e.message);}finally{$('#import-file').value='';}}
async function showSync(){if(server&&connection){await startJob('/api/sync',{},'Syncing your collection…');return;}modal('<h2>Bring your saves in.</h2><p>The web version works with imported files. To read your signed-in Xiaohongshu collection, open RedBot on your Mac using the included launcher, then choose Sync saves.</p><div class="settings-option"><div>Already have a backup?<small>Import it here. Your data stays in this browser.</small></div><button id="sync-import" class="btn primary">Import backup</button></div>');$('#sync-import').onclick=()=>{$('#modal').close();$('#import-file').click();};}
async function startJob(url,body,message){const b=url==='/api/sync'?$('#sync'):$('#load-content');if(b)b.disabled=true;try{const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await res.json();if(!res.ok)throw Error(d.error||'Could not start.');toast(message);pollJob(d.jobId,b);}catch(e){if(b)b.disabled=false;toast(e.message);}}
async function pollJob(id,button){try{const r=await fetch('/api/jobs/'+encodeURIComponent(id));const job=await r.json();if(job.status==='running'){if(button=== $('#sync')){$('#sync').querySelector('span').classList.add('spin');$('#footer-status').textContent='Syncing saves… you can keep browsing.';}setTimeout(()=>pollJob(id,button),1500);return;}if(button)button.disabled=false;$('#sync').querySelector('span').classList.remove('spin');if(job.status==='failed'){toast(job.error||'Could not sync. Your existing library is safe.');return;}const remote=await fetch('/api/library').then(r=>r.json());revision=remote.revision;const result=C.mergeItems(data.items,remote.items);data.items=result.items;data.scan=remote.scan;persist();render();if(detailId)openDetail(detailId,detailTab);toast(job.message||'Library updated.');}catch{if(button)button.disabled=false;toast('The local connection was interrupted. Your existing saves are safe.');}}
function loadContent(x){startJob('/api/enrich',{id:x.id},'Loading this post…');}
function bulk(action){if(!selected.size)return toast('Select one or more saves first.');if(action==='collection'){if(!data.collections.length)return newCollection();modal('<h2>Add to a collection.</h2><p>Choose where these saves belong.</p>'+data.collections.map(c=>`<button class="navitem" data-bulk-collection="${esc(c.id)}">▱ ${esc(c.name)}</button>`).join(''));document.querySelectorAll('[data-bulk-collection]').forEach(b=>b.onclick=()=>{applyBulk({collectionsAdd:b.dataset.bulkCollection});$('#modal').close();});return;}applyBulk({[({read:'read',favorite:'favorite',archive:'archived',trash:'trashed'})[action]]:true});}
function applyBulk(change){const before=JSON.parse(JSON.stringify(data.annotations));for(const id of selected){let a=annotation(id);data.annotations[id]={...a,...(change.collectionsAdd?{collections:[...new Set([...(a.collections||[]),change.collectionsAdd])]}:change)};}let count=selected.size;selected.clear();selecting=false;persist();render();toast(count+' saves updated.',()=>{data.annotations=before;persist();render();});}
function renderTasks(){const guides=data.guides||[],tasks=view==='tasks';$('#task-start').hidden=!guides.length||(!tasks&&view!=='all')||!!query;$('#guide-cards').hidden=!tasks;const cats=['All',...new Set(guides.map(g=>g.category))];$('#task-start').innerHTML=tasks?`<div class="task-categories">${cats.map(c=>`<button class="pill ${guideCategory===c?'active':''}" data-guide-category="${esc(c)}">${esc(c)}</button>`).join('')}</div>`:`<div><strong>What would you like to make?</strong><span>Your saved research has ${guides.length} practical starting points.</span></div><button class="btn" id="show-tasks">Use my saves ↗</button>`;const q=query.trim().toLowerCase();const visible=guides.filter(g=>(guideCategory==='All'||g.category===guideCategory)&&(!q||[g.title,g.method,g.prompt,g.category].join(' ').toLowerCase().includes(q)));$('#guide-cards').innerHTML=visible.map(g=>`<button class="guide-card" data-guide="${esc(g.id)}"><small>${esc(g.category)}</small><h2>${esc(g.title)}</h2><p>${esc(g.method)}</p><span>${g.sourceIds.length+g.resources.length} ${(g.sourceIds.length+g.resources.length)===1?'source':'sources'} · See the steps ↗</span></button>`).join('')||'<div class="empty"><h2>No matching methods.</h2><p>Try another word or a different category.</p></div>';}
function openGuide(id){const g=data.guides.find(x=>x.id===id);if(!g)return;modal(`<small class="eyebrow">${esc(g.category)}</small><h2>${esc(g.title)}</h2><p>${esc(g.method)}</p><h3>Try this</h3><ol class="guide-steps">${g.steps.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><h3>Copy into your coding assistant</h3><p class="muted">Edit the project and goal first. Nothing is installed or run by copying.</p><textarea id="guide-prompt" class="form-input prompt-area" aria-label="Editable execution prompt">${esc((goalText?'Current goal: '+goalText+'\n\n':'')+g.prompt)}</textarea><div class="modal-actions"><button id="copy-guide" class="btn primary">Copy instructions</button></div><details class="guide-sources"><summary>Sources & limitations</summary><p>${esc(g.limit)}</p><p>${esc(g.provenance||'')}</p>${g.sourceIds.map(n=>{const x=itemById(n);return x?`<button class="source-save" data-source-save="${esc(n)}">${esc(x.title)} ↗</button>`:'';}).join('')}${g.resources.map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).pathname.slice(1))} ↗</a>`).join('')}</details>`);$('#copy-guide').onclick=async()=>{const t=$('#guide-prompt');try{await navigator.clipboard.writeText(t.value);toast('Copied. Paste into your coding assistant to start.');}catch{t.focus();t.select();toast('Press Command+C or Control+C to copy the selected instructions.');}};document.querySelectorAll('[data-source-save]').forEach(b=>b.onclick=()=>{$('#modal').close();openDetail(b.dataset.sourceSave);});}
function showHelp(){modal(`<h2>Find it. Use it. Come back to it.</h2><div class="help-steps"><p><b>1. Start with a need</b><br>In For now, describe what you want to do. You do not need to remember the title.</p><p><b>2. Read the useful part</b><br>RedBot suggests one source and shows the saved text behind its choice. Missing text stays visibly unread.</p><p><b>3. Take one step</b><br>Try the suggested next action. Save for later keeps your place; Try another helps when the choice does not fit.</p></div><p>${server?'This Mac can use its existing Xiaohongshu connection. Scans may cover only part of your collection.':'This web preview uses example notes or material already saved in this browser. Xiaohongshu account sync is not available yet.'}</p><div class="modal-actions"><button id="help-backup" class="btn">Back up my saves</button><button id="help-connect" class="btn primary">Connection options</button></div>`);$('#help-connect').onclick=()=>{$('#modal').close();showConnection();};$('#help-backup').onclick=exportBackup;}
function currentStart(){if(goalChoice.startsWith('save:'))return C.semanticStart(data.items,data.guides||[],data,goalText,[{id:goalChoice.slice(5),kind:'save',score:1}]);if(aiBusy)return {status:'loading'};if(aiResult&&aiQuery===goalText&&!goalChoice)return aiResult;return C.chooseStart(data.items,data.guides||[],data,goalText,goalChoice);}
