 const examples=data.items.every(x=>x.id.startsWith('example-'))?[...(exampleAvailable('example-design')?['Make my page less cluttered.']:[]),...(exampleAvailable('example-first-use')?['Help someone get started with my app.']:[]),...(exampleAvailable('example-coffee')?['Find my iced coffee note.']:[])]:['Find a design idea I can use.','Find the coffee recipe I saved.'];
 panel.innerHTML=`${!goalText?paperStack():''}${!goalText&&plan?.status==='ready'?`<div class="continue-plan"><div><small>YOUR SAVED PLAN</small><strong>${esc(plan.goal)}</strong></div><button id="continue-plan" class="btn">Continue this plan ↗</button></div>`:''}${compact?`<details class="goal-edit"><summary>Your goal: ${esc(goalText)} <span>Edit</span></summary>`:''}<form id="goal-form"><label class="form-label" for="goal-input">What do you need right now?</label><textarea id="goal-input" class="goal-input" rows="2" maxlength="1000" placeholder="e.g. I saved a way to make my page less cluttered…">${esc(goalText)}</textarea><div class="goal-actions"><small>A rough description is enough. Any language is welcome.</small><button class="btn primary">Find a starting point →</button></div></form><div class="ai-controls"><button type="button" id="ai-toggle" class="text-btn">${aiEnabled?'Search by meaning · on':'Search by meaning'}</button><small id="ai-status" data-scores="${esc(JSON.stringify(aiScores))}" role="status">${esc(aiEnabled||aiBusy?aiStatus:'Optional · works on this device')}</small></div>${compact?'</details>':''}${!r?`<div class="goal-examples"><span>Or try</span>${examples.map(t=>`<button class="pill" data-goal-example="${esc(t)}">${esc(t)}</button>`).join('')}</div><p class="small-promise">One useful source. The part that matters. A next step.</p>${!data.items.length?'<p class="restore-note">Your library is empty. <button class="text-btn" id="goal-add">Add a save</button> to give RedBot something to choose from.</p>':''}`:startResult(r)}`;
 $('#ai-toggle').onclick=showAI;
 $('#goal-form').onsubmit=async e=>{e.preventDefault();if(aiBusy)return;goalText=$('#goal-input').value.trim();goalChoice='';aiResult=null;aiQuery='';const basic=C.chooseStart(data.items,data.guides||[],data,goalText);if(aiEnabled&&goalText&&basic.status!=='clarify'&&basic.status!=='empty'){aiBusy=true;aiStatus='Searching saved meaning on this device...';renderStart();try{const res=await RedBotAI.search(goalText,data.items,data.guides||[],data);aiScores=res.ranked;aiQuery=goalText;aiResult=C.semanticStart(data.items,data.guides||[],data,goalText,res.ranked);aiStatus='AI searched the saved text. Verify the suggested source.';}catch(err){aiStatus=err.message;toast('AI unavailable. Showing basic matching instead.');}finally{aiBusy=false;}}renderStart();($('#start-title')||$('#goal-input')).focus({preventScroll:true});};
 document.querySelectorAll('[data-goal-example]').forEach(b=>b.onclick=()=>{goalText=b.dataset.goalExample;goalChoice='';renderStart();});
