function startResult(r){
 if(r.status==='loading')return '<section class="decision-message"><h2>Finding a useful starting point...</h2><p>AI runs on this device. Your saves are unchanged.</p></section>';
 if(r.status==='empty')return `<div class="decision-message"><h2>Your saves come first.</h2><p>${esc(r.message)}</p><button class="btn primary" id="goal-add">Add a save</button></div>`;
 if(r.status==='clarify')return `<section class="decision-message"><small>ONE QUICK QUESTION</small><h2>${esc(r.question)}</h2><div class="clarify-options">${r.options.map(x=>`<button class="btn" data-goal-choice="${esc(x.choice)}">${esc(x.label)} ↗</button>`).join('')}</div>${!r.options.length?'<p>Try describing what feels wrong, or the result you want to achieve.</p>':''}</section>`;
 if(r.status==='no_match')return `<section class="decision-message"><h2>I haven’t found the right save yet.</h2><p>${esc(r.message)}</p><div class="modal-actions"><button class="btn" id="reset-goal-skips">Reset choices for this goal</button><button class="btn primary" id="different-goal">Try different words</button></div></section>`;
 const x=r.source,g=r.guide,unread=r.status==='needs_reading',raw=x?.summary||x?.readingNotes||x?.description||x?.transcript||'',terms=C.goalTerms(goalText);let at=terms.map(t=>raw.toLowerCase().indexOf(t)).find(n=>n>=0);const passage=raw.slice(Math.max(0,(at||0)-70),Math.max(0,(at||0)-70)+480);
 const cover=x&&(server&&!x.image?.startsWith('data:')?'/media/'+encodeURIComponent(x.id)+'.jpg':C.imageURL(x.image));
 return `<article class="starting-point"><div class="decision-label"><span>${unread?'NEEDS READING':'START HERE'}</span><small>${unread?'Title match only':r.observations.length?'Saved research':r.external?'External reference':'Saved text'}</small></div><h2 id="start-title" tabindex="-1">${esc(g?.title||x?.title)}</h2><p class="decision-reason">${esc(r.reason)}</p>${g?`<div class="chosen-method"><small>SUGGESTED METHOD · FROM YOUR TASK GUIDE</small><strong>${esc(g.method)}</strong></div>`:''}${x?`<div class="chosen-source">${cover?`<img src="${esc(cover)}" alt="" referrerpolicy="no-referrer">`:''}<div><small>FROM YOUR LIBRARY</small><strong>${esc(x.title)}</strong><span>${esc(x.author||'Saved source')}</span></div></div>`:''}${unread?'<div class="decision-caveat"><h3>Content has not been read.</h3><p>Open this save to read or load its available text. A title alone cannot tell me which part will help you.</p></div>':r.observations.length?`<section class="useful-part"><h3>The useful part</h3>${r.observations.map(p=>`<div class="observation"><span>${esc(p[0])}</span><p>${esc(p[1])}</p></div>`).join('')}</section>`:passage?`<section class="useful-part"><h3>The useful part</h3><p class="source-excerpt">${esc(passage)}${raw.length>passage.length?'…':''}</p></section>`:`<p class="decision-caveat">This method is linked from your saved task guide. The external project has not been installed or tested by this recommendation.</p>`}<div class="decision-primary">${x?`<button class="btn primary" id="goal-read">${unread?'Read this save':r.observations.length?'Open these reading notes':'Read the saved text'} ↗</button>`:g?.resources[0]?`<a class="btn primary" href="${esc(g.resources[0])}" target="_blank" rel="noopener noreferrer">Inspect this source ↗</a>`:''}${g&&!unread?'<button class="btn" id="goal-method">Use the steps & instructions</button>':''}</div>${!unread?`<section class="next-action"><small>YOUR NEXT STEP</small><p>${esc(r.next)}</p></section>`:''}<details class="guide-sources"><summary>About this suggestion</summary><p>Chosen from material already in this library. AI mode compares saved text by meaning; basic mode uses wording and curated guides. Neither mode watches the original videos.</p><p>${esc(r.limitations)}</p>${x?'<button class="text-btn" id="goal-original">Open original source ↗</button>':''}</details><div class="decision-feedback">${!unread?'<button class="text-btn" id="keep-plan">Save for later</button><button class="text-btn" id="goal-helped">This helped</button>':''}<button class="text-btn" id="goal-skip">Try another</button></div></article>`;
}

async function init(){document.querySelectorAll('button,input,select').forEach(b=>b.disabled=true);handleBrokenImages();try{const p=JSON.parse(localStorage.getItem(PREF)||'{}');layout=p.layout||layout;sort=p.sort||sort;data={...data,...(await browserRead()||JSON.parse(localStorage.getItem(KEY)||'{}'))};}catch{toast('The browser recovery copy could not be read. You can import a backup.');}try{const res=await fetch('/api/library',{signal:AbortSignal.timeout(2500)});if(res.ok&&res.headers.get('Content-Type')?.includes('application/json')){const d=await res.json();if(Array.isArray(d.items)){server=true;revision=d.revision;data={...data,...d};delete data.revision;if(!data.annotations)data.annotations={};if(!data.collections)data.collections=[]; // Mac disk is authoritative; browser recovery remains exportable.
$('#storage-label').textContent='Saved on your Mac';}}}catch{}if(server){try{connection=!!(await fetch('/api/capabilities').then(r=>r.json())).xiaohongshu;}catch{}}data.goalState=C.normalizeGoalState(data.goalState);data.items=data.items.map(C.normalize);data.guides=(data.guides||[]).map(C.normalizeGuide).filter(Boolean);render();document.querySelectorAll('button,input,select').forEach(b=>b.disabled=false);$('#navigation').parentElement.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)navigate(b.dataset.view);});$('#search').oninput=e=>{query=e.target.value;if(view==='start'&&query)navigate('all');limit=60;clearTimeout(renderTimer);renderTimer=setTimeout(render,90);};$('#filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){filter=b.dataset.filter;limit=60;render();}};$('#sort').onchange=e=>{sort=e.target.value;prefs();render();};$('#grid-view').onclick=()=>{layout='grid';prefs();render();};$('#list-view').onclick=()=>{layout='list';prefs();render();};$('#clear-filters').onclick=()=>{query='';$('#search').value='';filter='all';render();};$('#cards').onclick=e=>{const fav=e.target.closest('[data-favorite]'),open=e.target.closest('[data-open]');if(fav){const id=fav.dataset.favorite;patch(id,{favorite:!annotation(id).favorite});}else if(open){if(selecting){let id=open.dataset.open;selected.has(id)?selected.delete(id):selected.add(id);render();}else openDetail(open.dataset.open);}};$('#cards').onchange=e=>{if(e.target.dataset.select){let id=e.target.dataset.select;e.target.checked?selected.add(id):selected.delete(id);render();}};$('#load-more').onclick=()=>{limit+=60;render();};$('#home-button').onclick=$('#tab-start').onclick=()=>{goalText='';goalChoice='';aiResult=null;aiQuery='';navigate('start');};$('#tab-library').onclick=()=>navigate('all');$('#account-button').onclick=showConnection;$('#settings-button').onclick=showSettings;$('#add').onclick=showAdd;$('#empty-action').onclick=()=>data.items.length?navigate('all'):showAdd();$('#new-collection').onclick=newCollection;$('#library-settings').onclick=showSettings;$('#sync').onclick=showSync;$('#welcome-import').onclick=showConnection;$('#help').onclick=showHelp;if($('#demo-upgrade')){$('#demo-upgrade').hidden=data.demoVersion===2;$('#demo-upgrade').onclick=()=>{const seed=window.REDBOT_SEED;if(!seed)return;data.items=C.mergeItems(data.items,seed.items).items;const gm=new Map((data.guides||[]).map(g=>[g.id,g]));for(const g of seed.guides||[])if(!gm.has(g.id))gm.set(g.id,g);data.guides=[...gm.values()];data.demoVersion=2;persist();render();$('#demo-upgrade').hidden=true;toast('Examples added. Your other saves and notes are kept.');};}$('#guide-cards').onclick=e=>{const b=e.target.closest('[data-guide]');if(b)openGuide(b.dataset.guide);};$('#task-start').onclick=e=>{const c=e.target.closest('[data-guide-category]');if(c){guideCategory=c.dataset.guideCategory;renderTasks();}if(e.target.closest('#show-tasks'))navigate('tasks');};$('#import-file').onchange=e=>importFile(e.target.files[0]);$('#detail-backdrop').onclick=closeDetail;$('#select-mode').onclick=()=>{selecting=!selecting;if(!selecting)selected.clear();render();};$('#end-select').onclick=()=>{selected.clear();selecting=false;render();};$('#select-all').onclick=()=>{C.filterItems(data.items,data,view,filter,query,sort).slice(0,limit).forEach(x=>selected.add(x.id));render();};document.querySelectorAll('[data-bulk]').forEach(b=>b.onclick=()=>bulk(b.dataset.bulk));$('#mobile-menu').onclick=openNavigation;$('#mobile-close').onclick=$('#mobile-shade').onclick=closeNavigation;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close();});document.addEventListener('keydown',e=>{const editable=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(e.key==='Escape'){closeDetail();closeNavigation();}if(e.key==='/'&&!editable){e.preventDefault();if(view==='start')navigate('all');$('#search').focus();}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();if(view==='start')navigate('all');$('#search').focus();}if(e.key==='Tab'&&detailId){const focusable=[...$('#detail').querySelectorAll('button,a,input,select,textarea')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();document.body.classList.add('drop-zone');}});document.addEventListener('dragleave',e=>{if(!e.relatedTarget)document.body.classList.remove('drop-zone');});document.addEventListener('drop',e=>{document.body.classList.remove('drop-zone');if(e.dataTransfer.files.length){e.preventDefault();importFile(e.dataTransfer.files[0]);}});window.addEventListener('beforeunload',()=>{if(server&&pendingSave)saveServer();});}
ready=init();

function showAI(){if(location.protocol==='file:'){toast('Open the HTTPS beta for AI search. This offline file uses basic matching.');return;}modal(`<h2>Search by meaning, on this device.</h2><p>Download a multilingual AI model from Hugging Face and its runtime from jsDelivr. Your saved text is processed in this browser, not sent to an AI service.</p><p>The first download is large (roughly 120 MB plus runtime), so use Wi-Fi. It may take time and use device memory. Basic search keeps working without it. AI compares up to 300 current saves and methods; it cannot read an original video from a link.</p><div class="modal-actions"><button class="btn" id="ai-off">Use basic matching</button><button class="btn primary" id="ai-on">Download & enable AI</button></div>`);$('#ai-off').onclick=()=>{aiEnabled=false;aiResult=null;aiStatus='AI is off. Basic matching is available.';$('#modal').close();renderStart();};$('#ai-on').onclick=async()=>{$('#modal').close();aiBusy=true;aiStatus='Loading AI model...';renderStart();RedBotAI.progress(text=>{aiStatus=text;const el=$('#ai-status');if(el)el.textContent=text;});try{await RedBotAI.load();aiEnabled=true;aiStatus='AI ready. Describe your goal to search by meaning.';}catch(e){aiStatus=e.message;aiEnabled=false;}finally{aiBusy=false;renderStart();}};}

function paperStack(){return '<div class="paper-stack" aria-hidden="true"><div class="paper paper-back"><span>GOOD FINDS</span><i></i><i></i></div><div class="paper paper-front"><b class="ribbon"></b><span>SAVED FOR A REASON</span><strong>A little idea.<br>A useful next step.</strong><i></i><i></i><small>Keep the good part.</small></div><div class="paper-shadow"></div></div>';}
function renderWelcome(panel){panel.innerHTML=paperStack()+`<div class="welcome-actions">${server&&connection?'<button class="btn primary" id="connect-first">Connect Xiaohongshu →</button>':'<button class="btn primary" id="try-demo">Try with example notes →</button>'}<p class="connection-honesty">${server&&connection?'Use the account connected on this Mac. Your original saves stay where they are.':'Design preview · Xiaohongshu account sync is being built.'}</p>${server&&connection?'<button class="text-btn" id="try-demo">Explore an example first</button>':'<button class="text-btn" id="connect-first">About account connection</button>'}</div>`;$('#try-demo').onclick=loadDemo;$('#connect-first').onclick=showConnection;}
function loadDemo(){const seed=window.REDBOT_SEED;if(!seed)return toast('Examples could not load. Refresh this page and try again.');data.items=C.mergeItems(data.items,seed.items).items;const map=new Map((data.guides||[]).map(g=>[g.id,g]));for(const g of seed.guides||[])if(!map.has(g.id))map.set(g.id,g);data.guides=[...map.values()];data.demoVersion=3;persist();goalText='';goalChoice='';navigate('start');toast('Original example notes are ready. Your existing saves are kept.');}
let navReturn;
function openNavigation(){navReturn=document.activeElement;document.body.classList.add('nav-open');$('#sidebar').inert=false;$('main').inert=true;$('#mobile-close').focus();}
function closeNavigation(){document.body.classList.remove('nav-open');$('#sidebar').inert=true;$('main').inert=false;if(navReturn?.isConnected)navReturn.focus();}
async function showConnection(){
 if(!server||!connection){modal('<h2>Your saves, without the uploading.</h2><p>Connecting Xiaohongshu will let RedBot bring in your saved posts. Account sync is not available in this web preview yet.</p><p>You can try finding a useful starting point with original example notes today. They are separate from anyone’s real Xiaohongshu account.</p><div class="modal-actions"><button class="btn primary" id="connection-demo">Try example notes →</button></div>');$('#connection-demo').onclick=()=>{$('#modal').close();loadDemo();};return;}
 modal('<h2>Your Xiaohongshu connection.</h2><p id="connection-status" role="status">Checking this Mac’s connection…</p><div id="connection-actions"></div>');
 try{const res=await fetch('/api/connection',{signal:AbortSignal.timeout(30000)});if(!res.ok)throw Error();const status=await res.json();if(!$('#connection-status'))return;if(status.state==='connected'){$('#connection-status').textContent='Signed in on this Mac. Refresh your saved posts; existing notes and plans are kept. This connector may return only part of your collection.';$('#connection-actions').innerHTML='<button class="btn primary" id="connection-sync">Sync my saves →</button>';$('#connection-sync').onclick=()=>{$('#modal').close();showSync();};}else{$('#connection-status').textContent='Sign-in is needed in the local Xiaohongshu connector. This preview cannot complete sign-in on your behalf. Your saved library is still available.';$('#connection-actions').innerHTML='<button class="btn" id="connection-retry">Check again</button>';$('#connection-retry').onclick=showConnection;}}
 catch{if($('#connection-status'))$('#connection-status').textContent='The local connection could not be checked. Your saved library is still available. Reopen the updated local app and try again.';}
}
